import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function daysAgo(days: number): Date {
  const date = new Date();
  date.setDate(date.getDate() - days);
  return startOfDay(date);
}

interface ReportDatePickerProps {
  onChange?: (date: Date | null) => void;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selected, setSelected] = useState<Date | null>(() => startOfDay(new Date()));

  const quickOptions = [
    { label: 'Сегодня', getValue: () => daysAgo(0) },
    { label: 'Вчера', getValue: () => daysAgo(1) },
    { label: 'Неделя назад', getValue: () => daysAgo(7) },
  ];

  const handleValueChange = (date: Date | null) => {
    setSelected(date);
    onChange?.(date);
  };

  const isQuickOptionActive = (getValue: () => Date) => {
    if (!selected) return false;
    return startOfDay(selected).getTime() === getValue().getTime();
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-sm)',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты"
        style={{ display: 'flex', gap: 'var(--jx-r-sm)', flexWrap: 'wrap' }}
      >
        {quickOptions.map((option) => (
          <JxChip
            key={option.label}
            active={isQuickOptionActive(option.getValue)}
            onClick={() => handleValueChange(option.getValue())}
          >
            {option.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={selected} onValueChange={handleValueChange} />
    </div>
  );
}

